// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

/**
 * Keeps commit-log records above a revision from being trimmed or having their rows released while a build worker needs
 * them. The applier creates the hold at the log head before the worker pins its snapshot; the worker narrows it to the
 * pinned revision, which can only be higher.
 */
final class AdjacencyRetentionHold {

	private volatile long revision;

	AdjacencyRetentionHold(long revision) {
		this.revision = revision;
	}

	/** Records strictly above this revision are retained. */
	long revision() {
		return revision;
	}

	/** Raises the hold to the pinned revision; lowering is refused because records may already be gone. */
	void narrowTo(long pinnedRevision) {
		if (pinnedRevision < revision) {
			throw new IllegalStateException(
					"pinned revision " + pinnedRevision + " is below the retention hold " + revision);
		}
		revision = pinnedRevision;
	}
}
